example.fix_applied:
# Before
@property
def login_button(self):
    """FN:login_button - Returns login button locator."""
    return self.page.locator(".btn-primary")

# After
@property
def login_button(self):
    """FN:login_button - Returns login button locator."""
    return self.page.get_by_role("button", name="Sign In")

# Before def test_dashboard_load(self, page: Page): page.goto("/dashboard") page.wait_for_timeout(2000) assert page.locator(".dashboard").is_visible()
# After from playwright.sync_api import expect
def test_dashboard_load(self, page: Page): page.goto("/dashboard") expect(page.get_by_role("heading", name="Dashboard")).to_be_visible()
